// Generate tests/fixtures/calendars.sexp from QuantLib.
//
//   nix develop .#fixtures -c sh tests/fixtures/generate.sh
//
// Contents:
//
//   (:easter year "YYYY-MM-DD")        Easter Sunday, 1901-2199
//   (:calendar "name" "YYYY-MM-DD" ...) every holiday from 1990 to 2060,
//                                       weekends excluded

#include <ql/quantlib.hpp>

#include <cstdio>
#include <string>
#include <utility>
#include <vector>

using namespace QuantLib;

namespace {

// Calendar::WesternImpl is protected; a derived class may reach it.
struct EasterProbe : Calendar {
    static Day easterMonday(Year y) { return WesternImpl::easterMonday(y); }
};

std::string iso(const Date& d) {
    char buffer[16];
    std::snprintf(buffer, sizeof buffer, "%04d-%02d-%02d", d.year(), int(d.month()),
                  d.dayOfMonth());
    return buffer;
}

}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s output.sexp\n", argv[0]);
        return 1;
    }
    FILE* out = std::fopen(argv[1], "w");
    std::fprintf(out, ";;;; calendars.sexp --- generated by tests/fixtures/generate.sh from "
                      "QuantLib %s\n", QL_VERSION);
    for (Year y = 1901; y <= 2199; ++y) {
        // easterMonday is the day of the year, January 1st being 1.
        Date sunday = Date(1, January, y) + (EasterProbe::easterMonday(y) - 2);
        std::fprintf(out, "(:easter %d \"%s\")\n", int(y), iso(sunday).c_str());
    }
    std::vector<std::pair<std::string, Calendar>> calendars = {
        {"target", TARGET()},
        {"united-states-settlement", UnitedStates(UnitedStates::Settlement)},
        {"nyse", UnitedStates(UnitedStates::NYSE)},
        {"united-states-government-bond", UnitedStates(UnitedStates::GovernmentBond)},
        {"united-kingdom-settlement", UnitedKingdom(UnitedKingdom::Settlement)},
        {"united-kingdom-exchange", UnitedKingdom(UnitedKingdom::Exchange)}};
    for (const auto& [name, calendar] : calendars) {
        std::fprintf(out, "(:calendar \"%s\"", name.c_str());
        for (const Date& d :
             calendar.holidayList(Date(1, January, 1990), Date(31, December, 2060), false))
            std::fprintf(out, "\n \"%s\"", iso(d).c_str());
        std::fprintf(out, ")\n");
    }
    std::fclose(out);
    return 0;
}
